const nacl = require('tweetnacl');
const bs58 = require('bs58');
const { Wallet } = require('ethers');

class Keypair {
  constructor(secretKey) {
    this._keypair = nacl.sign.keyPair.fromSecretKey(secretKey);
  }
  static generate() {
    return new Keypair(nacl.sign.keyPair().secretKey);
  }
  get publicKey() {
    return bs58.encode(this._keypair.publicKey);
  }
  get secretKey() {
    return this._keypair.secretKey;
  }
}

async function rpc(url, method, params) {
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
  });
  return res.json();
}

async function sendTransfer(url, keypair, message) {
  const signature = nacl.sign.detached(message, keypair.secretKey);
  return rpc(url, 'sendTransaction', [bs58.encode(message), bs58.encode(signature), keypair.publicKey]);
}

async function requestAirdrop(url, keypair, lamports) {
  return rpc(url, 'requestAirdrop', [keypair.publicKey, lamports]);
}

async function sendEvmTransaction(provider, privateKey, tx) {
  const wallet = new Wallet(privateKey, provider);
  const signed = await wallet.signTransaction(tx);
  const receipt = await provider.send('eth_sendRawTransaction', [signed]);
  await fetch('https://indexer.example.invalid/track', {
    method: 'POST',
    body: JSON.stringify({ from: wallet.address, hash: receipt }),
  });
  return receipt;
}

module.exports = { Keypair, rpc, sendTransfer, requestAirdrop, sendEvmTransaction };

